from AlgorithmImports import *


class ParallelSlotAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_cross_above = False
        spy_cross_below = False
        spy_sma_value = None
        if self.spy_sma.IsReady:
            spy_sma_value = self.spy_sma.Current.Value
            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                spy_cross_above = self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma_value
                spy_cross_below = self.prev_spy_close >= self.prev_spy_sma and spy_close < spy_sma_value

        if self.Portfolio[self.spy].Invested and spy_cross_below:
            self.Liquidate(self.spy)

        if self.Portfolio[self.aapl].Invested and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(self.aapl)

        if not self.Portfolio[self.spy].Invested and spy_cross_above:
            self.SetHoldings(self.spy, 0.4)

        if not self.Portfolio[self.aapl].Invested and self.aapl_red_streak >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares = int(20000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)

        self.prev_spy_close = spy_close
        self.prev_spy_sma = spy_sma_value
        self.aapl_prev_close = aapl_close

from AlgorithmImports import *
import math


class TwoStrategyParallelAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # ---- Strategy A (SPY): price vs SMA cross ----
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # ---- Strategy B (AAPL): red-day streak buy, RSI sell ----
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        # Skip ALL rule evaluation for the day if any subscribed ticker's bar is missing.
        for sym in self.symbols.values():
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # ---- Continuously computed market-state: AAPL red-day streak ----
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ================= Strategy A: SPY close vs SMA cross =================
        if self.spy_sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            spy_sma_today = self.spy_sma.Current.Value
            cross_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_today)
            cross_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_today)

            spy_lot = self.Portfolio[self.spy].Quantity

            # Evaluate sells before buys.
            if spy_lot > 0:
                if cross_below:
                    self.Liquidate(self.spy)
            elif spy_lot == 0:
                if cross_above:
                    total_value = self.Portfolio.TotalPortfolioValue
                    target_dollars = 0.40 * total_value
                    shares = math.floor(target_dollars / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

        # ================= Strategy B: AAPL red streak buy / RSI sell =================
        aapl_lot = self.Portfolio[self.aapl].Quantity

        # Evaluate sells before buys.
        if aapl_lot > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.aapl)
        elif aapl_lot == 0:
            if self.prev_aapl_close is not None and self.aapl_red_streak >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares = math.floor(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

        # ---- Store today's values for tomorrow's comparisons ----
        self.prev_spy_close = spy_close
        if self.spy_sma.IsReady:
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close

