        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA period not specified in the strategy description; using 50 as a standard trend-cross length.
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilder, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.spy_cross_above = False
        self.spy_cross_below = False

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Continuously update market-state quantities from each ticker's own data, independent of the daily gate.
        if data.Bars.ContainsKey(self.spy):
            today_close = data.Bars[self.spy].Close
            sma_ready = self.spy_sma.IsReady
            today_sma = self.spy_sma.Current.Value if sma_ready else None

            if sma_ready and self.prev_spy_close is not None and self.prev_spy_sma is not None:
                self.spy_cross_above = self.prev_spy_close <= self.prev_spy_sma and today_close > today_sma
                self.spy_cross_below = self.prev_spy_close >= self.prev_spy_sma and today_close < today_sma
            else:
                self.spy_cross_above = False
                self.spy_cross_below = False

            self.prev_spy_close = today_close
            if sma_ready:
                self.prev_spy_sma = today_sma
        else:
            self.spy_cross_above = False
            self.spy_cross_below = False

        if data.Bars.ContainsKey(self.aapl):
            today_close = data.Bars[self.aapl].Close
            if self.aapl_prev_close is not None:
                if today_close < self.aapl_prev_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_prev_close = today_close

        # Skip all rule evaluation if any subscribed ticker's bar is missing today.
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        # Slot 1 - Strategy A (SPY): evaluate sell before buy.
        spy_qty = self.Portfolio[self.spy].Quantity
        if spy_qty > 0:
            if self.spy_cross_below:
                self.Liquidate(self.spy)
        else:
            if self.spy_cross_above:
                target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                price = data.Bars[self.spy].Close
                qty = math.floor(target_value / price)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)

        # Slot 2 - Strategy B (AAPL): evaluate sell before buy.
        aapl_qty = self.Portfolio[self.aapl].Quantity
        if aapl_qty > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.aapl)
        else:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    price = data.Bars[self.aapl].Close
                    qty = math.floor(20000 / price)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)

