class ParallelSlotStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Moving average period is unspecified in the strategy text; using a standard 50-day SMA.
        self.sma_spy = self.SMA(self.spy, 50, Resolution.Daily)
        self.rsi_aapl = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Slot 1 - Strategy A (SPY) private lot/state
        self.prev_close_spy = None
        self.prev_sma_spy = None
        self.shares_a = 0

        # Slot 2 - Strategy B (AAPL) private lot/state
        self.prev_close_aapl = None
        self.red_streak_aapl = 0
        self.shares_b = 0

    def OnData(self, data: Slice):
        for sym in self.all_symbols:
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        self._run_strategy_a(spy_close)
        self._run_strategy_b(aapl_close)

    def _run_strategy_a(self, spy_close):
        sma_ready = self.sma_spy.IsReady
        sma_today = self.sma_spy.Current.Value if sma_ready else None

        if sma_ready and self.prev_close_spy is not None and self.prev_sma_spy is not None:
            crosses_above = self.prev_close_spy <= self.prev_sma_spy and spy_close > sma_today
            crosses_below = self.prev_close_spy >= self.prev_sma_spy and spy_close < sma_today

            # Sells before buys
            if self.shares_a > 0:
                if crosses_below:
                    self.MarketOrder(self.spy, -self.shares_a)
                    self.shares_a = 0
            else:
                if crosses_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = math.floor(target_value / spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)
                        self.shares_a = qty

        self.prev_close_spy = spy_close
        if sma_ready:
            self.prev_sma_spy = sma_today

    def _run_strategy_b(self, aapl_close):
        if self.prev_close_aapl is not None:
            if aapl_close < self.prev_close_aapl:
                self.red_streak_aapl += 1
            else:
                self.red_streak_aapl = 0

        # Sells before buys
        if self.shares_b > 0:
            if self.rsi_aapl.IsReady and self.rsi_aapl.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.shares_b)
                self.shares_b = 0
        else:
            if self.red_streak_aapl >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    qty = math.floor(20000 / aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.shares_b = qty

        self.prev_close_aapl = aapl_close

