        if self.spy_sma.IsReady:
            spy_sma_now = self.spy_sma.Current.Value

            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                cross_above = self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma_now
                cross_below = self.prev_spy_close >= self.prev_spy_sma and spy_close < spy_sma_now

                spy_qty = self.Portfolio[self.spy].Quantity

                if spy_qty > 0 and cross_below:
                    self.Liquidate(self.spy)
                elif spy_qty == 0 and cross_above:
                    target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                    shares = math.floor(target_value / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma_now

        # ---- Slot 2 - Strategy B: AAPL red streak / RSI ----
        if self.prev_aapl_close is not None:
