        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Moving-average length not specified by the strategy text; 50-day is used as the reference MA.
        self.sma_period = 50
        self.spy_sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Slot 1 - Strategy A (SPY) private lot
        self.strategyA_shares = 0
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Slot 2 - Strategy B (AAPL) private lot
        self.strategyB_shares = 0
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Market-state quantity: consecutive red-day streak for AAPL, computed continuously.
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---- Slot 1: Strategy A (SPY) ----
        spy_sma_ready = self.spy_sma.IsReady
        if spy_sma_ready and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            spy_sma_today = self.spy_sma.Current.Value
            crossed_above = self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma_today
            crossed_below = self.prev_spy_close >= self.prev_spy_sma and spy_close < spy_sma_today

            if self.strategyA_shares > 0:
                if crossed_below:
                    self.MarketOrder(self.spy, -self.strategyA_shares)
            else:
                if crossed_above:
                    target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                    qty = math.floor(target_value / spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)

        # ---- Slot 2: Strategy B (AAPL) ----
        if self.strategyB_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategyB_shares)
        else:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    qty = math.floor(20000 / aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)

        # Update "yesterday" references for next bar's cross detection.
        if spy_sma_ready:
            self.prev_spy_close = spy_close
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return

        if orderEvent.Symbol == self.spy:
            self.strategyA_shares += orderEvent.FillQuantity
        elif orderEvent.Symbol == self.aapl:
            self.strategyB_shares += orderEvent.FillQuantity

